package com.hozefa.threepattipro.nativeapp;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class SessionLeaderboardTest {
 private Map<String,Object> m(Object... p){return SessionLeaderboard.FirebaseMap.of(p);}
 private List<Map<String,Object>> list(Map<String,Object>... p){return Arrays.asList(p);}
 private Map<String,Object> session(String id,boolean online,boolean active,long start){Map<String,Object>s=m("id",id,"sessionName",id,"startTime",new Date(start),"endTime",active?null:new Date(start+100),"status",active?"playing":"stopped");if(online)s.put("source","online");return s;}
 private Map<String,Object> round(String id,String session,boolean online,long score){Map<String,Object> r=m("id",id,"type","hukum","timestamp","2026-10-20T10:00:00Z","sessionId",session,"playerIds",Arrays.asList("a","b"),"hukumId","a","partnerIds",Arrays.asList("b"),"result","win","scoreChanges",m("a",score,"b",score/2));if(online){r.put("source","online");r.put("handId",id);}return r;}
 private List<Map<String,Object>> players(){return list(m("id","a","name","Alpha"),m("id","b","name","Beta"));}
 @Test public void catalogLiveFirstNewestFirstAndNoDuplicates(){Map<String,Object>a=session("a",false,true,100),b=session("b",true,true,200),c=session("c",false,false,400);List<Map<String,Object>> result=SessionLeaderboard.catalog(list(a,b,c),list(m("id","b","source","online","endTime",null,"status","playing","startTime",200L)));assertEquals(Arrays.asList("b","a","c"),Arrays.asList(SessionLeaderboard.id(result.get(0)),SessionLeaderboard.id(result.get(1)),SessionLeaderboard.id(result.get(2))));}
 @Test public void explicitSessionIdsPreventMixingAndDuplicateHands(){Map<String,Object>one=session("one",false,false,1),two=session("two",false,false,2),online=session("cf2_x",true,false,3);Map<String,Object> a=round("r1","one",false,100),b=round("r2","two",false,500),c=round("r3","cf2_x",true,360);assertEquals(100,SessionLeaderboard.model(players(),list(a,b,c),list(one,two,online),one,null).byId.get("a").points);assertEquals(1,SessionLeaderboard.rounds(list(c,new HashMap<>(c)),list(online),"cf2_x").size());}
 @Test public void timestampLegacyMatchingRejectsOverlapsAndOnlineRounds(){long t=SessionLeaderboard.time("2026-10-20T10:00:00Z");Map<String,Object>s=session("legacy",false,false,t-10);s.put("endTime",new Date(t+10));Map<String,Object>r=round("r","",false,10);assertEquals(1,SessionLeaderboard.rounds(list(r),list(s),"legacy").size());Map<String,Object>other=new HashMap<>(s);other.put("id","overlap");assertEquals(0,SessionLeaderboard.rounds(list(r),list(s,other),"legacy").size());r.put("source","online");assertEquals(0,SessionLeaderboard.rounds(list(r),list(s),"legacy").size());}
 @Test public void authoritativeLiveAndPendingTotalsReplaceHistoryNeverAdd(){Map<String,Object>s=session("cf2_x",true,true,1),remote=new HashMap<>(s);remote.putAll(m("totalRounds",2,"pendingExports",1,"leaderboard",list(m("id","a","name","Alpha","score",180,"roundsPlayed",2,"last",-180))));Map<String,Object>r=round("r1","cf2_x",true,360);ScoreboardModel live=SessionLeaderboard.model(players(),list(r),list(s),s,remote);assertEquals(180,live.byId.get("a").points);assertEquals(2,live.byId.get("a").played);assertEquals(-180,live.byId.get("a").last);s.put("endTime",new Date(100));s.put("status","stopped");remote.putAll(s);assertEquals(180,SessionLeaderboard.model(players(),list(r),list(s),s,remote).byId.get("a").points);}
 @Test public void completedHistorySupersedesEqualCountRemoteAndFresherHistoryWins(){Map<String,Object>s=session("cf2_x",true,false,1),r=round("r1","cf2_x",true,360),remote=new HashMap<>(s);remote.putAll(m("totalRounds",1,"pendingExports",0,"leaderboard",list(m("id","a","score",999,"roundsPlayed",1))));assertEquals(360,SessionLeaderboard.model(players(),list(r),list(s),s,remote).byId.get("a").points);remote.put("totalRounds",0);remote.put("status","playing");remote.put("endTime",null);assertEquals(360,SessionLeaderboard.model(players(),list(r),list(s),s,remote).byId.get("a").points);}
 @Test public void noInventedLiveTotalsAndNoLeadersBeforeCompletedHand(){Map<String,Object>s=session("cf2_x",true,true,1);assertTrue(SessionLeaderboard.model(players(),list(round("r","cf2_x",true,360)),list(s),s,null).rows.isEmpty());assertTrue(ScoreboardModel.standings(list(m("id","a","score",0,"roundsPlayed",0))).rows.isEmpty());}
 @Test public void botAndArchivedNamesInSessionNeverChangeLifetimeRoster(){Map<String,Object>s=session("cf2_x",true,false,1),r=round("r","cf2_x",true,360);r.put("scoreChanges",m("a",360,"bot_2",180));r.put("participants",list(m("playerId","bot_2","name","Computer 2")));List<Map<String,Object>> roster=players();ScoreboardModel model=SessionLeaderboard.model(roster,list(r),list(s),s,null);assertEquals("Computer 2",model.byId.get("bot_2").name);assertEquals(180,model.byId.get("bot_2").points);assertEquals(1,model.byId.get("bot_2").played);assertFalse(new ScoreboardModel(roster,list(r),Collections.emptyList()).byId.containsKey("bot_2"));assertFalse(((List<?>)r.get("playerIds")).contains("bot_2"));}
 @Test public void remoteCompetitionRanksAndDistinctParticipants(){ScoreboardModel b=ScoreboardModel.standings(list(m("id","a","score",10,"roundsPlayed",1),m("id","b","score",10,"roundsPlayed",1),m("id","a","score",999,"roundsPlayed",1),m("id","c","score",0,"roundsPlayed",1)));assertEquals(3,b.rows.size());assertEquals(2,b.leaders.size());assertEquals(3,b.byId.get("c").rank);}
 @Test public void deletedSessionsExcludedAndStoppedNeverLive(){Map<String,Object>s=session("gone",true,true,1);s.put("status","deleted");assertTrue(SessionLeaderboard.catalog(list(s),Collections.emptyList()).isEmpty());assertFalse(SessionLeaderboard.active(s));assertFalse(SessionLeaderboard.active(null));}
}
